import { Pool } from "pg";

export type RideStatus = "requested" | "assigned" | "in_progress" | "completed" | "cancelled";

export interface Ride {
  id: string;
  riderId: string;
  driverId: string | null;
  status: RideStatus;
  requestedAt: Date;
}

interface RideRow {
  id: string;
  rider_id: string;
  driver_id: string | null;
  status: RideStatus;
  requested_at: Date;
}

function toRide(row: RideRow): Ride {
  return {
    id: row.id,
    riderId: row.rider_id,
    driverId: row.driver_id,
    status: row.status,
    requestedAt: row.requested_at,
  };
}

export class RideRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Ride | null> {
    const { rows } = await this.pool.query<RideRow>(
      "SELECT id, rider_id, driver_id, status, requested_at FROM rides WHERE id = $1",
      [id],
    );
    return (rows[0] as unknown as Ride) ?? null;
  }

  async findActiveForRider(riderId: string): Promise<Ride | null> {
    const { rows } = await this.pool.query<RideRow>(
      `SELECT id, rider_id, driver_id, status, requested_at FROM rides
       WHERE rider_id = $1 AND status IN ('requested', 'assigned', 'in_progress')
       LIMIT 1`,
      [riderId],
    );
    return rows[0] ? toRide(rows[0]) : null;
  }

  async create(riderId: string): Promise<Ride> {
    const { rows } = await this.pool.query<RideRow>(
      `INSERT INTO rides (rider_id, status, requested_at) VALUES ($1, 'requested', now())
       RETURNING id, rider_id, driver_id, status, requested_at`,
      [riderId],
    );
    return toRide(rows[0]);
  }

  async setStatus(id: string, status: RideStatus): Promise<void> {
    await this.pool.query("UPDATE rides SET status = $1 WHERE id = $2", [status, id]);
  }
}

import { RideRepository, Ride } from "./rideRepository";

export interface DriverRegistry {
  markAvailable(driverId: string): Promise<void>;
}

export interface Notifier {
  rideCancelled(ride: Ride, by: "rider" | "driver"): Promise<void>;
}

export class RideNotFound extends Error {}
export class RideConflict extends Error {}

export class DispatchService {
  constructor(
    private readonly rides: RideRepository,
    private readonly drivers: DriverRegistry,
    private readonly notifier: Notifier,
  ) {}

  async requestRide(riderId: string): Promise<Ride> {
    const active = await this.rides.findActiveForRider(riderId);
    if (active) {
      throw new RideConflict(`rider ${riderId} already has ride ${active.id}`);
    }
    return this.rides.create(riderId);
  }

  async cancelRide(rideId: string, riderId: string): Promise<Ride> {
    const ride = await this.rides.findById(rideId);
    if (!ride || ride.riderId !== riderId) {
      throw new RideNotFound(`ride ${rideId} not found`);
    }
    if (ride.status === "in_progress" || ride.status === "completed") {
      throw new RideConflict(`ride ${rideId} cannot be cancelled in status ${ride.status}`);
    }
    if (ride.status === "cancelled") {
      return ride;
    }

    await this.rides.setStatus(ride.id, "cancelled");
    if (ride.driverId) {
      await this.drivers.markAvailable(ride.driverId);
    }
    const cancelled: Ride = { ...ride, status: "cancelled" };
    await this.notifier.rideCancelled(cancelled, "rider");
    return cancelled;
  }
}

import { Request, Response } from "express";
import { DispatchService, RideNotFound, RideConflict } from "./dispatchService";

export function makeRideHandlers(dispatch: DispatchService) {
  return {
    async request(req: Request, res: Response) {
      const riderId = res.locals.riderId as string;
      try {
        const ride = await dispatch.requestRide(riderId);
        res.status(201).json(ride);
      } catch (err) {
        if (err instanceof RideConflict) return res.status(409).json({ error: err.message });
        throw err;
      }
    },

    async cancel(req: Request, res: Response) {
      const riderId = res.locals.riderId as string;
      try {
        const ride = await dispatch.cancelRide(req.params.rideId, riderId);
        res.json(ride);
      } catch (err) {
        if (err instanceof RideNotFound) return res.status(404).json({ error: err.message });
        if (err instanceof RideConflict) return res.status(409).json({ error: err.message });
        throw err;
      }
    },
  };
}
